def find_hits(drafts, needle):
  n=needle.lower();hits=[]
  for d in drafts:
    m=d.get('message',{})
    hay=' '.join(str(m.get(k,'')) for k in ['to','subject','messageText']).lower()
    if n in hay:
      hits.append({'draft_id':d.get('id'),'to':m.get('to'),'subject':m.get('subject')})
  return hits
